import numpy as np
from rdkit import Chem
m=Chem.MolFromMolFile('graph.mol',removeHs=False)
p=np.loadtxt('optimized.xyz',skiprows=2,usecols=(1,2,3))
for group in [[0,15,16,17,18],[19,20,21,22,23],[9,10,11,12,13,14]]:
 print('Ti-C distances',np.linalg.norm(p[group]-p[24],axis=1));v=p[group].mean(0)-p[24];print('Ti-centroid',np.linalg.norm(v))
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();d=np.linalg.norm(p[i]-p[j]);
 if d>1.75:print('long bond',i,j,d)
for g,h in [([0,15,16,17,18],[19,20,21,22,23])]:
 v1=p[g].mean(0)-p[24];v2=p[h].mean(0)-p[24];print('CpTiCp angle',np.degrees(np.arccos(v1@v2/(np.linalg.norm(v1)*np.linalg.norm(v2)))))
